from fractions import Fraction


def routing_kernel(request):
    """Normalize the request into a routing kernel.

    Returns a dict with:
      stations: list of station IDs (in request order)
      delivered: list of delivered station IDs
      outgoing: mapping station ID -> list of (target, Fraction prob, int time)
      can_deliver: set of station IDs that can reach a delivered station
    """
    stations = list(request["stations"])
    delivered = list(request["delivered"])
    delivered_set = set(delivered)

    # Group routes by origin, preserving order and parallel routes.
    by_origin = {}
    for route in request["routes"]:
        by_origin.setdefault(route["from"], []).append(route)

    outgoing = {}
    for sid in stations:
        rows = []
        routes = by_origin.get(sid, [])
        total = sum(route["weight"] for route in routes)
        for route in routes:
            prob = Fraction(route["weight"], total)
            rows.append((route["to"], prob, route["time"]))
        outgoing[sid] = rows

    # Compute can_deliver via reverse reachability from delivered stations.
    reverse = {sid: [] for sid in stations}
    for sid in stations:
        for target, _prob, _time in outgoing[sid]:
            if target in reverse:
                reverse[target].append(sid)

    can_deliver = set(delivered_set)
    stack = list(delivered_set)
    while stack:
        node = stack.pop()
        for pred in reverse.get(node, []):
            if pred not in can_deliver:
                can_deliver.add(pred)
                stack.append(pred)

    return {
        "stations": stations,
        "delivered": delivered,
        "outgoing": outgoing,
        "can_deliver": can_deliver,
    }

from fractions import Fraction


def station_outcomes(kernel):
    """Compute success probability and conditional mean time for each station.

    For each station s:
      success[s] = P(reach a delivered station)
      mean_if_success[s] = E[total time | success], or None if success == 0

    We solve a linear system over exact rationals. Let p_s = P(success from s)
    and m_s = E[time until success from s] (unconditional, 0 if never succeeds).

    For a delivered station: p = 1, m = 0.
    For a non-delivered station with outgoing rows (target t, prob q, time w):
        p_s = sum q * p_t
        m_s = sum q * (w + m_t)   (only meaningful when p_s > 0)
    For a non-delivered station with no outgoing rows: p = 0, m = 0.

    Stations that cannot reach a delivered station have p = 0 and m = 0, so
    their conditional mean is None.
    """
    stations = kernel["stations"]
    delivered = set(kernel["delivered"])
    outgoing = kernel["outgoing"]
    can_deliver = kernel["can_deliver"]

    n = len(stations)
    idx = {sid: i for i, sid in enumerate(stations)}

    # Build linear system A * x = b for p (success probabilities).
    A = [[Fraction(0) for _ in range(n)] for _ in range(n)]
    b = [Fraction(0) for _ in range(n)]

    for i, sid in enumerate(stations):
        if sid in delivered:
            A[i][i] = Fraction(1)
            b[i] = Fraction(1)
        else:
            rows = outgoing.get(sid, [])
            if not rows:
                A[i][i] = Fraction(1)
                b[i] = Fraction(0)
            else:
                A[i][i] = Fraction(1)
                for target, prob, _time in rows:
                    j = idx[target]
                    A[i][j] -= prob

    p = _solve(A, b)

    # Build linear system for m (unconditional expected time).
    A2 = [[Fraction(0) for _ in range(n)] for _ in range(n)]
    b2 = [Fraction(0) for _ in range(n)]

    for i, sid in enumerate(stations):
        if sid in delivered:
            A2[i][i] = Fraction(1)
            b2[i] = Fraction(0)
        else:
            rows = outgoing.get(sid, [])
            if not rows:
                A2[i][i] = Fraction(1)
                b2[i] = Fraction(0)
            else:
                A2[i][i] = Fraction(1)
                for target, prob, time in rows:
                    j = idx[target]
                    A2[i][j] -= prob
                    b2[i] += prob * time

    m = _solve(A2, b2)

    result = {}
    for sid in stations:
        i = idx[sid]
        ps = p[i]
        if ps == 0:
            result[sid] = {
                "success": [0, 1],
                "mean_if_success": None,
            }
        else:
            mean = m[i] / ps
            result[sid] = {
                "success": [ps.numerator, ps.denominator],
                "mean_if_success": [mean.numerator, mean.denominator],
            }

    return result


def _solve(A, b):
    """Gaussian elimination with exact Fractions. Returns solution vector."""
    n = len(A)
    M = [row[:] + [b[i]] for i, row in enumerate(A)]
    for col in range(n):
        # Find pivot
        pivot = None
        for r in range(col, n):
            if M[r][col] != 0:
                pivot = r
                break
        if pivot is None:
            continue
        M[col], M[pivot] = M[pivot], M[col]
        pv = M[col][col]
        for r in range(n):
            if r != col and M[r][col] != 0:
                factor = M[r][col] / pv
                for c in range(col, n + 1):
                    M[r][c] -= factor * M[col][c]
    x = [Fraction(0) for _ in range(n)]
    for i in range(n):
        if M[i][i] != 0:
            x[i] = M[i][n] / M[i][i]
    return x

